<div class="scene-layer direction-layer"><div class="compass-visual"><span class="compass-n">N</span><span class="compass-e">E</span><span class="compass-s">S</span><span class="compass-w">W</span><i class="needle"></i><b></b></div><div class="waypoint waypoint-shelter"><svg class="icon"><use href="#i-shelter"></use></svg><span>SHELTER</span></div><div class="waypoint waypoint-food"><svg class="icon"><use href="#i-food"></use></svg><span>FOOD</span></div><div class="waypoint waypoint-sos"><svg class="icon"><use href="#i-sos"></use></svg><span>SOS MESSAGE</span></div><div class="route-dashes"></div></div>
